update public.role_permissions set is_enabled=true where role in ('admin','admin_dir','admin_acct','admin_it','super_admin') and permission_key='admin:approve_admin_requests'; update public.role_permissions set is_enabled=true where role in ('admin','admin_dir','admin_acct','super_admin') and permission_key='admin:approve_payments'; update public.role_permissions set is_enabled=false where role='admin_it' and permission_key='admin:approve_payments'; insert into public.role_permissions(role,permission_key,is_enabled) select r.role,'admin:view_subscribers',true from (values ('admin'),('admin_dir'),('admin_acct'),('admin_it'),('super_admin')) r(role) where not exists(select 1 from public.role_permissions p where p.role=r.role and p.permission_key='admin:view_subscribers'); update public.role_permissions set is_enabled=true where role in ('admin','admin_dir','admin_acct','admin_it','super_admin') and permission_key='admin:view_subscribers';
create or replace function public.search_estate_subscribers(_search text default null,_estate_code text default null,_status text default null) returns setof public.estate_subscriptions language sql security definer set search_path=public as $$ select s from public.estate_subscriptions s where public.user_has_permission(auth.uid(),'admin:view_subscribers') and (_estate_code is null or _estate_code='' or s.estate_code=upper(_estate_code)) and (_status is null or _status='' or s.subscription_status=_status) and (_search is null or _search='' or s.subscription_number ilike '%'||_search||'%' or s.estate_name ilike '%'||_search||'%' or coalesce(s.order_id::text,'') ilike '%'||_search||'%' or coalesce(s.user_id::text,'') ilike '%'||_search||'%') order by s.created_at desc $$;
revoke all on function public.search_estate_subscribers(text,text,text) from public; grant execute on function public.search_estate_subscribers(text,text,text) to authenticated;
create or replace function public.can_approve_admin_request(_user_id uuid default auth.uid()) returns boolean language sql security definer set search_path=public stable as $$ select public.user_has_permission(coalesce(_user_id,auth.uid()),'admin:approve_admin_requests') $$;
revoke all on function public.can_approve_admin_request(uuid) from public; grant execute on function public.can_approve_admin_request(uuid) to authenticated;
